<div class="page-heading"><div><p class="context">Stockage</p><h1>Stocks & rangement</h1><p>Consultez les quantités physiques et les réservations, puis déplacez les marchandises.</p></div><a class="button secondary" href="/?page=catalog&t=stock_movement">Historique des mouvements</a></div>
<form class="filters" method="get"><input type="hidden" name="page" value="stock"><?php inputField('q','Article, lot ou palette',$_GET['q']??'','search',false);foreach(['article_id'=>'article','owner_id'=>'owner','zone_id'=>'zone','lot_id'=>'lot'] as $key=>$t)selectField($key,Catalog::LABELS[$key],$catalog->options($t),$_GET[$key]??'',true);selectField('sort','Trier',[['id'=>'article','label'=>'Article'],['id'=>'lot','label'=>'Lot'],['id'=>'quantity','label'=>'Quantité décroissante']],$_GET['sort']??'article');filterEnd('stock'); ?>
<section class="panel"><?php $result=$reports->stock($_GET);dataTable(array_map(fn($r)=>['Article'=>$r['sku'].' / '.$r['article_name'],'Lot'=>$r['lot_code'],'Propriétaire'=>$r['owner_name'],'Emplacement'=>$r['location_code'],'Zone'=>$r['zone_name'],'Palette reçue'=>$r['pallet_code'],'Physique (u)'=>$r['qty'],'Réservé (u)'=>$r['reserved_qty'],'Disponible (u)'=>$r['available_qty'],'DLC'=>$r['expires_on'],'Blocage'=>$r['blocked']?'Oui':'Non'],$result['rows']));pagination($result['total'],$result['page']);exportPrint('stock'); ?></section>
<div class="split-layout no-print"><section class="panel"><h2>Transférer un stock</h2><?php startForm('transfer');selectField('receipt_item_id','Palette reçue / provenance',$catalog->options('receipt_item'));selectField('source_id','Emplacement source',$catalog->options('location'));selectField('dest_id','Destination',$catalog->options('location'));inputField('qty','Quantité entière','','number');inputField('reason','Motif du déplacement'); ?><button>Transférer</button></form></section><section class="panel"><h2>Ajuster l’inventaire</h2><p>Une correction ajoute un mouvement daté et motivé.</p><?php startForm('adjust');selectField('receipt_item_id','Palette reçue / provenance',$catalog->options('receipt_item'));selectField('location_id','Emplacement',$catalog->options('location'));inputField('delta','Variation entière (+ ou −)','','number');inputField('reason','Motif de correction'); ?><button class="secondary">Enregistrer la correction</button></form></section></div>
<section class="panel no-print"><h2>Proposer des emplacements</h2><form method="get" class="filters"><input type="hidden" name="page" value="stock"><?php selectField('suggest_article','Article',$catalog->options('article'),$_GET['suggest_article']??'');inputField('suggest_qty','Quantité',$_GET['suggest_qty']??1,'number'); ?><button>Vérifier les capacités</button></form><?php if(!empty($_GET['suggest_article'])){$w=new Warehouse($db,(int)$user['id']);$suggestions=$w->suggestions((int)$_GET['suggest_article'],Warehouse::positive($_GET['suggest_qty']??0));echo '<p>Propositions indicatives, revérifiées sous verrou à la validation.</p>';dataTable(array_map(fn($l)=>['Emplacement compatible'=>$l['code']],$suggestions));} ?></section>
